        result = []
        while remaining:
            start = min(remaining)
            remaining.remove(start)
            todo = [start]
            part = {start}
            while todo:
                r, c = todo.pop()
                for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                    if p in remaining:
                        remaining.remove(p)
                        part.add(p)
                        todo.append(p)
            result.append(part)
        return sorted(result, key=lambda p: min(p))

    targets = set()
    black = set()
    mirror_rows = []
    white = set()

    for r in range(N):
        for c in range(N):
            corner = board[3*r][3*c]
            center = board[3*r+1][3*c+1]
            if center == "Y":
                targets.add((r, c))
            if corner == "B":
                black.add((r, c))
            if corner == "S":
                mirror_rows.append(r)
            if center == "W":
                white.add((r, c))

    if not mirror_rows:
        return board[:]

    counts = {}
    for r in mirror_rows:
        counts[r] = counts.get(r, 0) + 1
    mirror = max(sorted(counts), key=counts.get)
    pieces = components(black)

    # Selection index zero denotes the mirror.
    selected = 0
    mirror_selected = any(
        (mirror, c) in white and board[3*mirror][3*c] == "S"
        for c in range(N)
    )
    if not mirror_selected:
        candidates = [
            i + 1 for i, part in enumerate(pieces)
