import re


# Logical coordinates. The visible upper target pattern and the replay
# feedback establish this half; complete it by a half-turn about (7, 12).
_TARGET_SEED = {
    (1, 7), (1, 9), (1, 11), (1, 13), (1, 15), (1, 17),
    (2, 13), (2, 14), (2, 15),
    (3, 7), (3, 13), (3, 14), (3, 15), (3, 17),
    (4, 9), (4, 11), (4, 13), (4, 15),
    (5, 8), (5, 16),
    (7, 9), (7, 15),
}
_INITIAL_TARGETS = _TARGET_SEED | {
    (14 - r, 24 - c) for r, c in _TARGET_SEED
}


def predict(board_lines, action):
    """
    Deterministic, board-local predictor.

    Target completion for the truncated layout-replacement transition
    is inferred; subsequent target positions are read from the board.
    """
    if len(board_lines) != 64 or any(len(row) != 64 for row in board_lines):
        raise ValueError("Expected 64 strings of length 64")

    board = [list(row) for row in board_lines]
    text = str(action).strip().upper()

    def finish():
        return ["".join(row) for row in board]

    def paint(r, c, edge, centre=None):
        if not (0 <= r < 21 and 0 <= c < 21):
            return
        y, x = 3 * r, 3 * c
        for dy in range(3):
            board[y + dy][x:x + 3] = [edge] * 3
        if centre is not None:
            board[y + 1][x + 1] = centre

    def increment():
        for r in range(64):
            if board[r][63] == "Y":
                board[r][63] = "O"
                break

    def components(cells):
        remaining = set(cells)
        result = []
        while remaining:
            seed = min(remaining)
            remaining.remove(seed)
            group = {seed}
            pending = [seed]
            while pending:
                r, c = pending.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        q = (r + dr, c + dc)
                        if q in remaining:
                            remaining.remove(q)
                            group.add(q)
                            pending.append(q)
            result.append(group)
        return result

    def reflected(shape, axis_r=5, axis_c=3):
        result = set()
        for r, c in shape:
            result.add((r, 2 * axis_c - c))
            result.add((2 * axis_r - r, c))
            result.add((2 * axis_r - r, 2 * axis_c - c))
        return {
            (r, c) for r, c in result
            if 0 <= r < 21 and 0 <= c < 21
        }

    # Layout replacement observed in transitions 0 and 18.
    if text == "LEFT" and board[0][21] == "S":
        board[:] = [["b"] * 63 + ["Y"] for _ in range(63)]
        board.append(["B"] * 63 + ["Y"])

        for r in range(21):
            paint(r, 3, "S", "b")
        for c in range(21):
            paint(5, c, "S", "W")

        for r, c in _INITIAL_TARGETS:
            paint(r, c, "Y")

        main = {(16, 6), (16, 8), (19, 6), (19, 8)}
        main.update(
            (r, c) for r in (17, 18) for c in range(5, 10)
        )
        right = {
            (13, 19),
            (14, 19),
            (15, 18), (15, 19),
            (16, 18),
            (17, 17), (17, 18),
            (18, 17),
            (19, 17),
        }
        shapes = main | right

        for r, c in reflected(shapes):
            paint(
                r, c, "c",
                "Y" if (r, c) in _INITIAL_TARGETS else "c"
            )
        for r, c in shapes:
            paint(
                r, c, "B",
                "Y" if (r, c) in _INITIAL_TARGETS else "b"
            )
        return finish()

    black = {
        (r, c)
        for r in range(21)
        for c in range(21)
        if board[3 * r][3 * c] == "B"
    }
    groups = components(black)

    # A target's centre remains Y under either kind of shape.
    # This makes the hidden target layer recoverable from the image.
    targets = {
        (r, c)
        for r in range(21)
        for c in range(21)
        if board[3 * r + 1][3 * c + 1] == "Y"
        or board[3 * r][3 * c] == "Y"
    }

