def predict(board_lines, action):
    import re

    original = tuple(board_lines)
    if len(original) != 64 or any(len(s) != 64 for s in original):
        raise ValueError("Expected 64 strings of length 64")

    def normalize(a):
        if isinstance(a, str):
            text = a.strip().upper()
            if text.startswith("MOUSE"):
                numbers = re.findall(r"-?\d+", text)
                if len(numbers) >= 2:
                    return ("MOUSE", int(numbers[0]), int(numbers[1]))
            return text
        if isinstance(a, (tuple, list)) and len(a) >= 3:
            if str(a[0]).upper() == "MOUSE":
                return ("MOUSE", int(a[1]), int(a[2]))
        return str(a).upper()

    action = normalize(action)

    patterns = (
        ("..NNR", "..N..", "NNN..", "N....",
         "NNN..", "..N..", "..NNR"),
        (".....R", "RYYYYY"),
        (".R.....", "ppp....", "p.p....", "p.p....",
         "p.pppp.", "p....pR", "pppppp."),
    )

    def rotate(pattern):
        height, width = len(pattern), len(pattern[0])
        return tuple(
            "".join(pattern[height - 1 - r][c]
                    for r in range(height))
            for c in range(width)
        )

    orientations = []
    for pattern in patterns:
        forms = [pattern]
        for _ in range(3):
            forms.append(rotate(forms[-1]))
        orientations.append(forms)

    # Scene: (piece poses, selected piece, white status pixels).
    # Pose: (top pixel row, left pixel column, clockwise quarter-turns).
    initial_scene = (
        ((14, 8, 0), (11, 32, 0), (29, 29, 0)),
        0,
        0,
    )

    def piece_cells(scene):
        poses, _, _ = scene
        result = []
        for index, (r0, c0, rotation) in enumerate(poses):
            occupied = {}
            for r, line in enumerate(orientations[index][rotation]):
                for c, color in enumerate(line):
                    if color != ".":
                        occupied[(r0 + 3 * r, c0 + 3 * c)] = color
            result.append(occupied)
        return result

    def render(scene):
        _, selected, count = scene
        board = [["O"] * 64 for _ in range(64)]
