            color = "c"
            active = [v for index, v in occupants if index == selected]
            if active:
                color = active[0]
                if color == "R" and sum(v == "R" for _, v in occupants) > 1:
                    color = "G"
            for r in range(r0, r0 + 3):
                for c in range(c0, c0 + 3):
