    if board[0][0] == "O" and name in ("UP", "LEFT"):
        board = [["b"] * 64 for _ in range(64)]
        board[0][16:48] = ["c"] * 32
        for color, shape in _SHAPES.items():
            row, col = _ORIGINS[color]
            _paint(board, shape, row, col, inactive=(color != "S"))
        return ["".join(line) for line in board]

    pieces = {color: _find_piece(board, color) for color in _SHAPES}

    if name == "MOUSE":
        if mouse is None:
            return ["".join(line) for line in board]

        target = next(
            (
                color
                for color, piece in pieces.items()
                if piece is not None and _hit(piece, *mouse)
            ),
            None,
        )
        if target is None or pieces[target][3]:
            return ["".join(line) for line in board]

        replacement_order = {
            "N": ("S",),
            "S": ("O",),
            "O": ("Y", "N"),
            "Y": ("O", "N"),
        }
        replaced = next(
            (
                color
                for color in replacement_order[target]
                if pieces[color] is not None and pieces[color][3]
            ),
            None,
        )
        if replaced is not None:
            shape, row, col, _, _ = pieces[replaced]
            _paint(board, shape, row, col, inactive=True)

        shape, row, col, _, _ = pieces[target]
        _paint(board, shape, row, col)

        if replaced == "N" and target in ("O", "Y"):
            board[0][16] = "W"

    elif name in ("UP", "DOWN", "LEFT", "RIGHT", "SPACE"):
        if name == "SPACE":
            orange = pieces["O"]
            if orange is not None and orange[3] and orange[4] == 0:
                target = "O"
            else:
                target = next(
                    (
                        color
                        for color in ("N", "O", "S", "Y")
                        if pieces[color] is not None and pieces[color][3]
                    ),
                    None,
                )
        else:
            target = next(
                (
                    color
                    for color in ("S", "O", "N", "Y")
                    if pieces[color] is not None and pieces[color][3]
                ),
                None,
            )

        if target is not None:
            shape, row, col, _, rotation = pieces[target]
            new_shape = shape
            new_row, new_col = row, col

            if name == "SPACE":
                new_shape = _rotate(shape)
            else:
                dr, dc = {
                    "UP": (-3, 0),
                    "DOWN": (3, 0),
                    "LEFT": (0, -3),
                    "RIGHT": (0, 3),
                }[name]
                new_row += dr
                new_col += dc

            old_pixels = {
                (row + 3 * y + dy, col + 3 * x + dx)
                for y, line in enumerate(shape)
                for x, color in enumerate(line)
                if color != "."
                for dy in range(3)
                for dx in range(3)
            }
            destination = {
                (new_row + 3 * y + dy, new_col + 3 * x + dx)
                for y, line in enumerate(new_shape)
                for x, color in enumerate(line)
                if color != "."
                for dy in range(3)
                for dx in range(3)
            }
            legal = all(
                1 <= r < 64
                and 0 <= c < 64
                and ((r, c) in old_pixels or board[r][c] == "b")
                for r, c in destination
            )
            if legal:
                _paint(board, shape, row, col, erase=True)
                _paint(board, new_shape, new_row, new_col)

                if target == "S" and name == "RIGHT" and col == 11:
                    board[0][17] = "W"
                if target == "O" and name == "SPACE" and rotation == 0:
                    board[0][17] = "W"
                if target == "N" and name == "SPACE" and rotation == 1:
                    board[0][18] = "W"

    return ["".join(line) for line in board]
