import re


def predict(board_lines, action):
    b = [list(row) for row in board_lines]
    if len(b) != 64 or any(len(row) != 64 for row in b):
        raise ValueError("Expected 64 strings of length 64")

    def rect(r0, r1, c0, c1, color):
        for r in range(r0, r1):
            b[r][c0:c1] = [color] * (c1 - c0)

    def indicator(index=None):
        if index is None:
            index = next(
                (c for c in range(64) if b[63][c] == "W"), None
            )
        if index is not None and 0 <= index < 64:
            b[63][index] = "G"

    def result():
        return ["".join(row) for row in b]

    if isinstance(action, str):
        name = action.strip().upper()
        numbers = re.findall(r"-?\d+", name)
        mouse = (
            tuple(map(int, numbers[:2]))
            if name.startswith("MOUSE") and len(numbers) >= 2
            else None
        )
    elif isinstance(action, (tuple, list)) and action:
        name = str(action[0]).upper()
        mouse = (
            tuple(map(int, action[1:3]))
            if name == "MOUSE" and len(action) >= 3
            else None
        )
    else:
        name, mouse = "", None

    player = next(
        (
            (r, c)
            for r in range(63)
            for c in range(63)
            if b[r][c] == "N"
        ),
        None,
    )

    def replacement_scene(resumed=False):
        rect(0, 64, 0, 64, "G")
        rect(8, 56, 0, 38, "c")
        rect(8, 56, 38, 64, "B")
        for r in range(8, 56, 4):
            rect(r, r + 2, 38, 40, "W")

        rect(12, 16, 20, 24, "g")
        rect(12, 14, 22, 24, "Y")
        rect(24, 28, 8, 12, "g")
        rect(24, 28, 12, 32, "R")
        rect(24, 28, 20, 24, "r")
        rect(24, 28, 32, 36, "g")
        rect(28, 32, 4, 8, "g")
        rect(40, 44, 4, 8, "g")

        rect(40, 44, 8, 28, "P")
        rect(40, 44, 16, 20, "M")

        # Active upper bridge: both checkerboard parities are blue.
        rect(28, 32, 8, 12, "b")

        # Inactive lower bridge: odd-parity pixels persist.
        for r in range(32, 40):
            for c in range(4, 8):
                if (r + c) % 2:
                    b[r][c] = "b"

        if resumed:
            rect(26, 28, 16, 18, "N")
        else:
            rect(30, 32, 6, 8, "N")

        for top, color in ((20, "M"), (38, "b")):
            rect(top, top + 3, 49, 56, color)
