        if b[20][24] == "Y":
            first_white = next(
                (c for c in range(64) if b[63][c] == "W"), 64
            )
            # Inferred distinction for the apparent resumed scene.
            replacement_scene(resumed=(0 < first_white <= 6))
            return result()

    if mouse == (40, 52):
        horizontal = b[28][8] == "b"
        for r in range(28, 32):
            for c in range(8, 12):
                if (r + c) % 2 == 0 and b[r][c] != "N":
                    b[r][c] = "c" if horizontal else "b"
        for r in range(32, 40):
            for c in range(4, 8):
                if (r + c) % 2 == 0 and b[r][c] != "N":
                    b[r][c] = "b" if horizontal else "c"
        if horizontal:
            indicator()
        return result()

    if mouse == (22, 52):
        vertical = b[32][16] == "P"
        for r0, r1, c0, c1 in (
