import re


def predict(board_lines, action):
    """Return a complete 64x64 board, deterministically and without state."""
    if len(board_lines) != 64 or any(len(s) != 64 for s in board_lines):
        raise ValueError("Expected 64 strings of length 64")

    original = list(board_lines)
    b = [list(s) for s in original]

    if isinstance(action, str):
        text = action.upper().strip()
        name = text.split("(")[0].strip()
        numbers = list(map(int, re.findall(r"-?\d+", text)))
    elif isinstance(action, (tuple, list)) and action:
        name = str(action[0]).upper()
        numbers = [int(x) for x in action[1:]]
    else:
        return original

    def finish():
        return ["".join(row) for row in b]

    def fill(r, c, h, w, color):
        # Reserve row 63 for the status strip.
        for rr in range(max(0, r), min(63, r + h)):
            for cc in range(max(0, c), min(64, c + w)):
                b[rr][cc] = color

    def outline(r, c, h, w, color="c"):
        fill(r, c, 1, w, color)
        fill(r + h - 1, c, 1, w, color)
        fill(r, c, h, 1, color)
        fill(r, c + w - 1, h, 1, color)

    def centers(h, w):
        rs = [1] if h == 3 else [2, 3]
        cs = [1] if w == 3 else [2, 3]
        return [(r, c) for r in rs for c in cs]

    def draw(obj, mark=None, edge=None):
        r, c, h, w, oldmark, _ = obj
        if mark is None:
            mark = oldmark
        fill(r, c, h, w, "N")
        for dr, dc in centers(h, w):
            b[r + dr][c + dc] = mark
        if edge is not None and h == w == 3:
            dc = 0 if edge == "LEFT" else 2
            for dr in range(3):
                b[r + dr][c + dc] = "W"

    def objects():
        found = []
        occupied = set()

        # Recognize larger objects first.
        for h, w in ((3, 6), (6, 3), (3, 3)):
            middle = set(centers(h, w))
            for r in range(64 - h):
                for c in range(65 - w):
                    if (r, c) in occupied:
                        continue
                    marks = {
                        b[r + dr][c + dc] for dr, dc in middle
                    }
                    if len(marks) != 1:
                        continue
                    mark = next(iter(marks))
                    if mark not in "BWc":
                        continue

                    variants = [None]
                    if h == w == 3 and mark == "W":
                        variants += ["LEFT", "RIGHT"]

                    for edge in variants:
                        good = True
                        for dr in range(h):
                            for dc in range(w):
                                expected = (
                                    mark if (dr, dc) in middle else "N"
                                )
                                if edge == "LEFT" and dc == 0:
                                    expected = "W"
                                if edge == "RIGHT" and dc == w - 1:
                                    expected = "W"
                                if b[r + dr][c + dc] != expected:
                                    good = False
                                    break
                            if not good:
                                break

                        if good:
                            found.append((r, c, h, w, mark, edge))
                            occupied.update(
                                (r + dr, c + dc)
                                for dr in range(h)
                                for dc in range(w)
                            )
                            break
        return found

    def advance_strip():
        for c in range(63, -1, -1):
            if b[63][c] == "c":
                b[63][c] = "W"
                return

    def adjacent(square, other, direction):
        r, c, h, w = square[:4]
        rr, cc, hh, ww = other[:4]
        if not (r < rr + hh and rr < r + h):
            return False
        if direction == "LEFT":
            return cc + ww == c
        return c + w == cc

    def refresh_edges():
        obs = objects()
        for obj in obs:
            if obj[2:4] != (3, 3) or obj[4] != "W":
                continue
            draw(obj, edge=None)
            for direction in ("LEFT", "RIGHT"):
                if any(
                    other != obj and adjacent(obj, other, direction)
                    for other in obs
                ):
                    draw(obj, edge=direction)
                    break

    def expanded_room(selected_row=54, strip=None):
        for r in range(63):
            b[r] = ["g"] * 64

        fill(0, 0, 63, 21, "w")
        fill(0, 24, 30, 39, "p")
        fill(30, 0, 33, 63, "w")
        outline(8, 8, 8, 5, "c")
        fill(24, 0, 6, 63, "p")

        # Revised layout: lower-right cutout in the purple band.
        fill(27, 30, 3, 33, "g")

        draw((33, 39, 3, 6, "B", None))
        draw((42, 33, 6, 3, "B", None))
        draw((selected_row, 36, 3, 3, "W", None))
        b[63] = list(strip if strip is not None else "c" * 64)

    overview = (
        original[0] == "g" * 64
        and original[31][13] == "W"
        and original[34][11] == "c"
    )
    if overview and name == "DOWN":
        expanded_room()
        return finish()

    obs = objects()
    active = next((o for o in obs if o[4] == "W"), None)

    if name == "MOUSE":
        if len(numbers) < 2:
            return original
        mr, mc = numbers[:2]
        target = next(
            (
                o for o in obs
                if o[0] <= mr < o[0] + o[2]
                and o[1] <= mc < o[1] + o[3]
            ),
            None,
        )
        if target is None or target == active:
            return original

        if active is not None:
            draw(active, mark="c")
        draw(target, mark="W")
        if target[2:4] == (3, 6):
            advance_strip()
        refresh_edges()
        return finish()

    directions = {
        "UP": (-3, 0),
        "DOWN": (3, 0),
        "LEFT": (0, -3),
        "RIGHT": (0, 3),
    }
    if name not in directions or active is None:
        return original

    r, c, h, w, mark, edge = active

    # Signature associated with the second recorded room change.
