    (6, 17), (6, 23), (6, 29), (6, 35), (6, 41),
    (54, 17), (54, 23), (54, 29), (48, 29),
    (42, 29), (42, 23), (42, 17), (36, 17),
    (30, 17), (30, 23), (30, 29), (24, 29),
    (18, 29), (18, 23), (18, 17), (12, 17),
)
_INITIAL = tuple("SbgpwwwYbSwpSwwbwbgYp")


def _rotate(values, operation):
    values = list(values)
    if operation == "long_left":
        return values[1:] + values[:1]
    if operation == "long_right":
        return values[-1:] + values[:-1]
    if operation == "row_left":
        values[:5] = values[1:5] + values[:1]
    elif operation == "row_right":
        values[:5] = values[4:5] + values[:4]
    return values


def _meter_length(moves):
    # Nearest-integer rounding for nonnegative multiples of 4/5.
    return (4 * moves + 2) // 5


def _recorded_phases():
    """Recover the indicator's fractional phase on recorded branches."""
    result = {}
    branches = (
        (
            "long_left", "row_left", "long_left", "long_left",
            "row_right", "long_right", "long_right", "long_right",
            "long_right", "row_left",
        ),
        ("row_left", "long_left", "row_right", "long_right"),
        ("row_left", "long_left", "long_left"),
    )
    for branch in branches:
        values = list(_INITIAL)
        result[(tuple(values), 0)] = 0
        for moves, operation in enumerate(branch, 1):
            values = _rotate(values, operation)
            result[(tuple(values), _meter_length(moves))] = moves
    return result


