    if isinstance(action, str):
        if not action.strip().upper().startswith("MOUSE"):
            return None
        numbers = re.findall(r"-?\d+", action)
        if len(numbers) >= 2:
            return int(numbers[0]), int(numbers[1])
        return None

    if isinstance(action, dict):
        name = str(
            action.get("type", action.get("action", "MOUSE"))
        ).upper()
        if name != "MOUSE":
            return None
        r = action.get("row", action.get("r"))
        c = action.get("col", action.get("c"))
        if r is not None and c is not None:
            return int(r), int(c)
        return None

    if isinstance(action, (tuple, list)):
        if len(action) == 3 and str(action[0]).upper() == "MOUSE":
            return int(action[1]), int(action[2])
        if len(action) == 2 and all(isinstance(x, int) for x in action):
