            board, 1, 10 + 5 * i, 1, 4,
            "N" if i < 4 else "B"
        )

    _arrow(board, 4, 7, False)
    _arrow(board, 4, 49, True)

    # Replay correction: red arrow origin is column 9, not column 7.
    _arrow(board, 34, 9, False)
    _arrow(board, 34, 35, True)

    for r in (4, 10):
