    if len(board_lines) != 64 or any(
        len(row) != 64 for row in board_lines
    ):
        raise ValueError(
            "Expected 64 strings, each containing 64 characters"
        )

    mouse = _mouse_position(action)
    if mouse is None:
        return list(board_lines)
