    overview = (
        board_lines[3][3] == "c"
        and board_lines[6][17] == "N"
    )
    if overview:
        if (r, c) in {(44, 54), (15, 6), (24, 14)}:
            return _replacement_layout()
        return list(board_lines)

    operation = None
    if 4 <= r <= 11:
        if 7 <= c <= 12:
            operation = "row_left"
        elif 49 <= c <= 54:
            operation = "row_right"
    elif 34 <= r <= 41:
        if 9 <= c <= 14:
            operation = "long_left"
        elif 35 <= c <= 40:
            operation = "long_right"

