        return list(board_lines)

    values = tuple(board_lines[y][x] for y, x in _CYCLE)
    if any(color not in "SbgpwYON" for color in values):
        return list(board_lines)

    black_length = 0
    while (
        black_length < 64
        and board_lines[black_length][0] == "B"
    ):
        black_length += 1

    moves = _PHASES.get((values, black_length))
    if moves is None:
        # Deterministic fallback for unrecorded configurations.
        candidates = [
            n for n in range(81)
            if _meter_length(n) == black_length
        ]
        moves = candidates[0] if candidates else 80

    board = [list(row) for row in board_lines]
    new_values = _rotate(values, operation)
    for (y, x), color in zip(_CYCLE, new_values):
        _paint(board, y, x, 4, 4, color)

    new_black_length = min(64, _meter_length(moves + 1))
    for y in range(black_length, new_black_length):
        board[y][0] = "B"

    return ["".join(row) for row in board]
