import re


def predict(board_lines, action):
    a = [list(row) for row in board_lines]

    def rect(r, c, h, w, color):
        for y in range(r, r + h):
            a[y][c:c + w] = [color] * w

    def find(color):
        return [
            (r, c)
            for r in range(1, 63)
            for c in range(64)
            if a[r][c] == color
        ]

    def blocks(color, size):
        cells = set(find(color))
        result = []
        while cells:
            r, c = min(cells)
            result.append((r, c))
            for y in range(r, r + size):
                for x in range(c, c + size):
                    cells.discard((y, x))
        return result

    def finish():
        return ["".join(row) for row in a]

    text = str(action).upper()
    mouse = None
    if "MOUSE" in text:
        nums = re.findall(r"-?\d+", text)
        if len(nums) >= 2:
            mouse = tuple(map(int, nums[:2]))
        name = "MOUSE"
    else:
        name = text.strip()

    initial = a[6][14] == "p" and a[6][30] == "S"
    if initial and name == "UP":
        for r in range(1, 63):
            a[r] = list("M" * 32 + "P" * 32)
        a[0] = ["B"] * 64
        a[63] = ["B"] * 64

        rect(6, 6, 52, 52, "B")
        for r in range(6, 58):
            for c in range(6, 58):
                perimeter = (
                    r < 10 or r >= 54 or c < 10 or c >= 54
                )
                central_divider = (
                    30 <= c < 34 and not 42 <= r < 46
                )
                horizontal_separator = 30 <= r < 34
                if perimeter or central_divider or horizontal_separator:
                    a[r][c] = "R" if (r + c) % 2 == 0 else "B"

        rect(30, 14, 4, 12, "N")
        rect(30, 38, 4, 12, "O")
        rect(14, 18, 4, 4, "O")
        rect(14, 42, 4, 4, "N")
        rect(42, 18, 4, 4, "N")
        rect(22, 18, 4, 4, "S")
        rect(22, 42, 4, 4, "S")
        rect(43, 31, 2, 2, "b")
        return finish()

    if mouse is not None:
        r, c = mouse
        if not (0 <= r < 64 and 0 <= c < 64):
            return finish()

        hit = a[r][c]
        if hit in ("b", "Y"):
            mapping = {"S": "w", "b": "Y"}
        elif hit in ("S", "w"):
            mapping = {"w": "S", "Y": "b"}
        else:
            mapping = {}

        for y in range(1, 63):
            for x in range(64):
                a[y][x] = mapping.get(a[y][x], a[y][x])
        return finish()

    directions = {
        "UP": (-4, 0),
        "DOWN": (4, 0),
        "LEFT": (0, -4),
        "RIGHT": (0, 4),
    }
    if name not in directions:
        return finish()

    large = blocks("S", 4)
    small = blocks("Y", 2)
    n = a[63].count("W")

    # Empirical border-indicator schedule from recorded visible states.
    tick = (
        (n == 0 and name == "LEFT" and bool(small))
        or (n == 1 and name == "DOWN" and bool(small))
        or (n == 2 and name == "LEFT" and bool(large))
        or (n == 3 and name == "UP" and (18, 18) in large)
        or (n == 4 and name == "UP" and (10, 18) in large)
        or (n == 5 and name == "LEFT" and bool(small))
        or (n == 6 and name == "LEFT" and (35, 27) in small)
        or (n == 7 and name == "UP" and (35, 19) in small)
    )

    def restore_piece(r, c, size):
        for y in range(r, r + size):
            for x in range(c, c + size):
                color = "B"
                if 14 <= y < 18:
                    if 18 <= x < 22:
                        color = "O"
                    elif 42 <= x < 46:
                        color = "N"
                if 42 <= y < 46 and 18 <= x < 22:
                    color = "N"
                a[y][x] = color

    def update_gates(positions):
        occupied = set(positions)
        rect(
            30, 14, 4, 12,
            "B" if (14, 42) in occupied else "N"
        )
        rect(
            30, 38, 4, 12,
            "B" if (14, 18) in occupied else "O"
        )

    dr, dc = directions[name]

    if small:
        r, c = small[0]
        nr, nc = r + dr, c + dc
        allowed = (
            1 <= nr and nr + 2 <= 63
            and 0 <= nc and nc + 2 <= 64
            and all(
                a[y][x] == "B"
                for y in range(nr, nr + 2)
                for x in range(nc, nc + 2)
            )
        )
        if allowed:
            rect(r, c, 2, 2, "B")
            rect(nr, nc, 2, 2, "Y")

    elif large:
        targets = [
            (r + dr, c + (dc if c < 32 else -dc))
            for r, c in large
        ]
        valid = all(
            1 <= r and r + 4 <= 63
            and 0 <= c and c + 4 <= 64
            for r, c in targets
        )
        hazard = valid and any(
            a[y][x] == "R"
            for r, c in targets
            for y in range(r, r + 4)
            for x in range(c, c + 4)
        )

        if hazard:
            for r, c in large:
                restore_piece(r, c, 4)
            for color in ("b", "Y"):
                for r, c in blocks(color, 2):
                    rect(r, c, 2, 2, "B")

            targets = [(22, 18), (22, 42)]
            update_gates(targets)
            for r, c in targets:
                rect(r, c, 4, 4, "S")
            rect(43, 31, 2, 2, "b")

        elif valid and all(
            a[y][x] in ("B", "O", "N", "S")
            for r, c in targets
            for y in range(r, r + 4)
            for x in range(c, c + 4)
        ):
            for r, c in large:
                restore_piece(r, c, 4)
            update_gates(targets)
            for r, c in targets:
                rect(r, c, 4, 4, "S")

    if tick and n < 64:
        a[0][63 - n] = "W"
        a[63][n] = "W"

