import re


def predict(board_lines, action):
    """Predict a complete board using observed movements and scene geometry."""
    if len(board_lines) != 64 or any(len(s) != 64 for s in board_lines):
        raise ValueError("Expected 64 strings of length 64")

    src = [list(s) for s in board_lines]
    out = [row[:] for row in src]

    def rect(r0, r1, c0, c1, color, preserve_markers=False):
        for r in range(max(0, r0), min(64, r1)):
            for c in range(max(0, c0), min(64, c1)):
                if not preserve_markers or src[r][c] != "r":
                    out[r][c] = color

    def finish():
        return ["".join(row) for row in out]

    def tick():
        for c in range(63, -1, -1):
            if out[63][c] == "G":
                out[63][c] = "c"
                break

    def mouse_position(a):
        if isinstance(a, str):
            if not a.upper().startswith("MOUSE"):
                return None
            nums = re.findall(r"-?\d+", a)
            return tuple(map(int, nums[:2])) if len(nums) >= 2 else None
        if isinstance(a, (tuple, list)):
            if len(a) == 3 and str(a[0]).upper() == "MOUSE":
                return int(a[1]), int(a[2])
            if len(a) == 2:
                return int(a[0]), int(a[1])
        if isinstance(a, dict):
            if "row" in a and "col" in a:
                return int(a["row"]), int(a["col"])
        return None

    pos = mouse_position(action)
    if pos is None:
        return finish()

    # Long horizontal light-gray component.
    horizontal = None
    for r in range(3, 22):
        c = 0
        while c < 61:
            if src[r][c] != "w":
                c += 1
                continue
            end = c
            while end < 64 and src[r][end] == "w":
                end += 1
            if end - c >= 18:
                horizontal = (r, c, end)
                break
            c = end
        if horizontal is not None:
            break

    # Long vertical light-gray component.
    vertical = None
    for c in range(30, 58):
        runs = []
        start = None
        for r in range(9, 43):
            occupied = src[r][c] in ("w", "r")
            if occupied and start is None:
                start = r
            if not occupied and start is not None:
                if r - start >= 12:
                    runs.append((start, r))
                start = None
        if start is not None and 43 - start >= 12:
