                "direction": (-1, 0),
                "length": 2
            },
            "Y": {
                "pivot": (10, 40),
                "direction": (0, 1),
                "length": 3
            },
            "b": {
                "pivot": (10, 49),
                "direction": (1, 0),
                "length": 1
            },
