        rect(out, 27, 18, 30, 60, "p")
        rect(out, 30, 3, 42, 6, "p")
        rect(out, 30, 57, 39, 60, "p")

        # Revised bottom geometry: an opening, not a continuous floor.
        rect(out, 39, 45, 42, 60, "p")

        for r, c in ((33, 52), (34, 51), (34, 53), (35, 52)):
            out[r][c] = "r"

        # Replacement control artwork remains inferred where undisclosed.
        for center, color in ((12, "b"), (31, "Y"), (50, "N")):
