        return original

    endpoints = {
        "N": arms["Y"]["pivot"],
        "Y": arms["b"]["pivot"],
        "b": endpoint,
    }
    for color, arm in arms.items():
        pr, pc = arm["pivot"]
        er, ec = endpoints[color]
        dr, dc = arm["direction"]
        distance = (er - pr) * dr + (ec - pc) * dc
        if distance < 0 or distance % 3:
