        moving_tiles = tiles_for(candidate, subtree)
        if (moving_tiles & fixed_tiles) - {selected_pivot}:
            return False
        for r, c in arm_pixels(candidate):
            if not (0 <= r < 45 and 0 <= c < 64):
                return False
            if (
                (r, c) not in old_pixels
                and board[r][c] not in ("B", "r")
            ):
                return False
        return True

