        trial = copy_arms()
        if trial[selected]["length"] + delta < 0:
            return original
        trial[selected]["length"] += delta
        dr, dc = trial[selected]["direction"]
        for color in order[index + 1:]:
            r, c = trial[color]["pivot"]
            trial[color]["pivot"] = (
                r + 3 * delta * dr,
                c + 3 * delta * dc
            )
        if valid(trial):
            candidate = trial

    if candidate is None:
        return original

    new_pixels = arm_pixels(candidate)
    if new_pixels == old_pixels:
        return original

    for r, c in old_pixels:
        board[r][c] = "B"
    for (r, c), color in new_pixels.items():
        board[r][c] = color

    strip_updates = {
        ((48, 12), (10, 52)): 63,
        ((57, 15), (13, 49)): 62,
        ((57, 15), (19, 49)): 61,
        ((48, 50), (25, 49)): 60,
        ((57, 9), (7, 46)): 59,
        ((57, 9), (7, 40)): 58,
        ((48, 31), (7, 25)): 57,
        ((57, 9), (25, 37)): 56,
    }
    strip_column = strip_updates.get((click, endpoint))
    if strip_column is not None:
        board[63][strip_column] = "c"

    return ["".join(row) for row in board]
