import re


def predict(board_lines, action):
    """Return the complete next 64x64 board without hidden mutable state."""
    board = [list(row) for row in board_lines]
    if len(board) != 64 or any(len(row) != 64 for row in board):
        raise ValueError("Expected 64 strings, each containing 64 cells.")

    colors = set("bNYpROM")

    def rect(r, c, h, w, color):
        for y in range(r, r + h):
            for x in range(c, c + w):
                if 0 <= y < 64 and 0 <= x < 64:
                    board[y][x] = color

    def outline(r, c, h, w, color):
        for y in range(r, r + h):
            for x in range(c, c + w):
                if y in (r, r + h - 1) or x in (c, c + w - 1):
                    if 0 <= y < 64 and 0 <= x < 64:
                        board[y][x] = color

    def piece_at(r, c):
        cells = [
            board[y][x]
            for y in range(r, r + 4)
            for x in range(c, c + 4)
        ]
        if cells[0] in colors and all(v == cells[0] for v in cells):
            return cells[0]

        if all(
            board[r + dy][c + dx]
            == ("g" if dy in (1, 2) and dx in (1, 2) else "c")
            for dy in range(4)
            for dx in range(4)
        ):
            return ""

        # Fixed clues and frame decorations are not ordinary slots.
        return None

    def draw_piece(r, c, color):
        rect(r, c, 4, 4, color or "c")
        if not color:
            rect(r + 1, c + 1, 2, 2, "g")

    def spend_move():
        for x in range(63, -1, -1):
            if board[53][x] == "g":
                board[53][x] = "G"
                break

    def frame(top, color, selected=False, left=18, right=45):
        bottom = top + 9

        if selected:
            # Exterior L-shaped brackets; no white interior corner pixels.
            for corner_y, outward_y in ((top, -1), (bottom, 1)):
                for corner_x, outward_x in ((left, -1), (right, 1)):
                    y = corner_y + outward_y
                    for x in range(corner_x - 1, corner_x + 2):
                        board[y][x] = "W"

                    x = corner_x + outward_x
                    for y in range(corner_y - 1, corner_y + 2):
                        board[y][x] = "W"

        outline(top, left, 10, right - left + 1, color)

    def initialize_seven_color_puzzle():
        rect(0, 0, 8, 64, "c")
        rect(0, 7, 8, 50, "B")
        for i, color in enumerate("OpRbNYM"):
            outline(1, 8 + 7 * i, 6, 6, color)

        rect(8, 0, 45, 64, "c")
        frame(18, "R", selected=True)
        frame(32, "N", selected=False)

        for r in (21, 35):
            for c in (21, 27, 33, 39):
                draw_piece(r, c, "")

        # Draw the connector after the red frame so it crosses row 27.
        rect(21, 33, 4, 4, "c")
        outline(21, 33, 4, 4, "N")
        rect(25, 34, 7, 2, "N")

        rect(53, 0, 1, 64, "g")
        rect(54, 0, 10, 64, "c")

        # Initial inventory order established by replay feedback.
        for i, color in enumerate("RpNOMbY"):
            draw_piece(57, 9 + 7 * i, color)

    mouse = None
    if isinstance(action, str):
        name = action.strip().upper()
        if name.startswith("MOUSE"):
            nums = re.findall(r"-?\d+", action)
            if len(nums) >= 2:
                mouse = (int(nums[0]), int(nums[1]))

    elif isinstance(action, dict):
        name = str(action.get("type", action.get("action", ""))).upper()
        if name == "MOUSE":
            mouse = (int(action["row"]), int(action["col"]))

    elif isinstance(action, (tuple, list)) and action:
        name = str(action[0]).upper()
        if name == "MOUSE":
            if len(action) >= 3:
                mouse = (int(action[1]), int(action[2]))
            elif len(action) == 2:
                mouse = tuple(map(int, action[1]))

    else:
        name = str(action).upper()

    if name == "SPACE":
        initial_legend = (
            board[0][17] == "B"
            and board[0][7] == "c"
            and [board[1][x] for x in (18, 25, 32, 39)]
            == list("bNYp")
        )
        if initial_legend:
            initialize_seven_color_puzzle()
        else:
            spend_move()

    elif mouse is not None:
        r, c = mouse

        # Inventory alignment follows the currently displayed legend.
        legend_starts = [
            x
            for x in range(1, 59)
            if board[1][x] in colors
            and board[1][x - 1] == "B"
            and all(
                board[1][x + k] == board[1][x]
                for k in range(6)
            )
        ]

        inventory_origins = (
            legend_starts or [8, 15, 22, 29, 36, 43, 50]
        )

        selected = [
