            and all(board[61][x + k] == "W" for k in range(6))
        ]

        clicked_inventory = next(
            (
                x
                for x in inventory_origins
                if 56 <= r <= 61 and x <= c <= x + 5
            ),
            None,
        )

        if clicked_inventory is not None:
            x = clicked_inventory
            if piece_at(57, x + 1) is not None:
                for old_x in selected:
                    if old_x != x:
                        outline(56, old_x, 6, 6, "c")
                outline(56, x, 6, 6, "W")

        elif selected and 8 <= r < 53:
            destination = None
            for y in range(max(8, r - 3), min(r, 49) + 1):
                for x in range(max(0, c - 3), min(c, 60) + 1):
                    content = piece_at(y, x)
                    if content is not None:
                        destination = (y, x, content)
                        break
                if destination is not None:
                    break

            if destination is not None:
                src_x = selected[0]
                source = piece_at(57, src_x + 1)
                if source is not None:
                    dst_r, dst_c, old_piece = destination
                    draw_piece(dst_r, dst_c, source)
                    draw_piece(57, src_x + 1, old_piece)
                    outline(56, src_x, 6, 6, "c")
                    spend_move()

    return ["".join(row) for row in board]

