        a[r + dy][c + dx] = dot

    def patrols(phase):
        # Return patrols in drawing order.
        def bounce(q, end):
            q %= 2 * end
            if q < end:
                return q, 1
            return 2 * end - q, -1

        i, sign = bounce(phase + 1, 2)
        short = (
            26 + 6 * i, 21,
