        )
        lower_boundary = next(
            (c for c in range(64) if board[36][c] == "W"), 64
        )
        new_upper = max(0, min(64, upper_boundary - displacement))
        new_lower = max(0, min(64, lower_boundary + displacement))

        pointer = [
            (r, c, board[r][c])
            for r in range(32, 64)
            for c in range(64)
            if board[r][c] in ("c", "Y")
