        fill_strip(33, 64, next_lower, lower, "G")
    else:
        fill_strip(1, 30, next_upper, upper, "G")
        fill_strip(33, 64, lower, next_lower, "W")

    for rr, cc, color in sprite:
        nc = cc + 3 * direction
        if left <= nc < right:
            board[rr][nc] = color

    consume_action()
    return ["".join(row) for row in board]
