def predict(board_lines, action):
    """Predict one transition; coordinates are zero-based raster coordinates."""
    original = list(board_lines)
    grid = [list(row) for row in original]

    if not isinstance(action, str):
        return original
    action = action.strip().upper()
    directions = {
        "UP": (-4, 0),
        "DOWN": (4, 0),
        "LEFT": (0, -4),
        "RIGHT": (0, 4),
    }
    if action not in directions and action != "SPACE":
        return original

    green = [
        (r, c)
        for r in range(63)
        for c in range(64)
        if grid[r][c] == "N"
    ]
    if not green:
        return original

    pr = (min(r for r, c in green) // 4) * 4
    pc = (min(c for r, c in green) // 4) * 4
    old_player = (pr, pc)

    edges = {
        "UP": [(pr, pc + k) for k in range(4)],
        "DOWN": [(pr + 3, pc + k) for k in range(4)],
        "LEFT": [(pr + k, pc) for k in range(4)],
        "RIGHT": [(pr + k, pc + 3) for k in range(4)],
    }
    facing = "UP"
    for name, cells in edges.items():
        if all(grid[r][c] == "W" for r, c in cells):
            facing = name
            break
    old_facing = facing

    # Box records: [top row, left column, border color].
    boxes = []
    perimeter = [
        (i, j)
        for i in range(4)
        for j in range(4)
        if i in (0, 3) or j in (0, 3)
    ]
    for r in range(0, 60, 4):
        for c in range(0, 64, 4):
            border = grid[r][c]
            if border not in ("c", "G", "W"):
                continue
            if not all(
                grid[r + i][c + j] == border
                for i, j in perimeter
            ):
                continue
            if all(
                grid[r + i][c + j] == "b"
                for i in (1, 2)
                for j in (1, 2)
            ):
                boxes.append([r, c, border])

    held = next(
        (i for i, box in enumerate(boxes) if box[2] == "W"),
        None,
    )

    def underlying(r, c):
        # The fixed destination artwork, including when covered by an object.
        if 28 <= r < 32 and 28 <= c < 40:
            return "b" if r in (28, 31) or c in (28, 39) else "g"
        return "w"

    def erase_tile(r, c):
        for i in range(4):
            for j in range(4):
                grid[r + i][c + j] = underlying(r + i, c + j)

    erase_tile(pr, pc)
    for r, c, border in boxes:
        erase_tile(r, c)

    def box_at(r, c, exclude=None):
        for i, box in enumerate(boxes):
            if i != exclude and box[0] == r and box[1] == c:
                return i
        return None

    def available(r, c, exclude=None):
        if not (0 <= r and r + 3 < 63 and 0 <= c and c + 3 < 64):
            return False
        if box_at(r, c, exclude) is not None:
            return False
        for i in range(4):
            for j in range(4):
                rr, cc = r + i, c + j
                ch = grid[rr][cc]
                if ch == "w":
                    continue
                if 28 <= rr < 32 and 28 <= cc < 40 and ch in ("b", "g"):
                    continue
                return False
        return True

    moved = False
    moved_held = False
    blocked_by_box = False
    empty_space_action = False

    if action == "SPACE":
        dr, dc = directions[facing]
        front = box_at(pr + dr, pc + dc)
        if held is not None:
            held = None
        elif front is not None:
            held = front
        else:
            empty_space_action = True
    else:
        facing = action
        dr, dc = directions[facing]
        nr, nc = pr + dr, pc + dc

        if held is None:
            blocked_by_box = box_at(nr, nc) is not None
            if available(nr, nc):
                pr, pc = nr, nc
                moved = True
        else:
            br, bc = nr + dr, nc + dc
            if available(nr, nc, held) and available(br, bc, held):
                pr, pc = nr, nc
                boxes[held][0] = br
                boxes[held][1] = bc
                moved = True
                moved_held = True
            else:
                # Keep the attachment geometry if a carrying move is blocked.
                facing = old_facing

    # Empirical status-strip updates supported by the recorded probes.
    strip = original[63]
    if (
        strip == "P" * 64
        and old_player == (44, 32)
        and moved
    ):
        grid[63][63] = "c"
    elif strip == "P" * 63 + "c":
        right_turn_into_box = (
            action == "RIGHT"
            and old_facing != "RIGHT"
            and blocked_by_box
        )
        if moved_held or right_turn_into_box or empty_space_action:
            grid[63][62] = "c"

    # Render boxes with highlighting derived from the final facing.
    dr, dc = directions[facing]
    front_position = (pr + dr, pc + dc)
    for index, (r, c, unused_border) in enumerate(boxes):
        if index == held:
            border = "W"
        elif (r, c) == front_position:
            border = "G"
        else:
            border = "c"
        for i in range(4):
            for j in range(4):
                grid[r + i][c + j] = (
                    border if i in (0, 3) or j in (0, 3) else "b"
                )

    # Render player and its directional white edge.
    for i in range(4):
        for j in range(4):
            white = (
                (facing == "UP" and i == 0)
                or (facing == "DOWN" and i == 3)
                or (facing == "LEFT" and j == 0)
                or (facing == "RIGHT" and j == 3)
            )
            grid[pr + i][pc + j] = "W" if white else "N"

    return ["".join(row) for row in grid]

