            and blocked_by_box
        )
        if moved_held or right_turn_into_box or empty_space_action:
            grid[63][62] = "c"

    # Render boxes with highlighting derived from the final facing.
    dr, dc = directions[facing]
    front_position = (pr + dr, pc + dc)
    for index, (r, c, unused_border) in enumerate(boxes):
        if index == held:
            border = "W"
        elif (r, c) == front_position:
            border = "G"
        else:
            border = "c"
        for i in range(4):
            for j in range(4):
