def predict(board_lines, action):
    """Observed movement model with a partially reconstructed initial reset."""
    src = list(board_lines)
    b = [list(row) for row in src]
    action = str(action).upper()

    def rect(r, c, h, w, color):
        for y in range(max(0, r), min(63, r + h)):
            for x in range(max(0, c), min(64, c + w)):
                b[y][x] = color

    def box(r, c, frame):
        rect(r, c, 4, 4, frame)
        rect(r + 1, c + 1, 2, 2, "b")

    def player(r, c, direction):
        rect(r, c, 4, 4, "N")
        if direction == "LEFT":
            rect(r, c, 4, 1, "W")
        elif direction == "RIGHT":
            rect(r, c + 3, 4, 1, "W")
        elif direction == "UP":
            rect(r, c, 1, 4, "W")
        else:
            rect(r + 3, c, 1, 4, "W")

    def background(r, c):
        for y in range(max(0, r), min(63, r + 4)):
            for x in range(max(0, c), min(64, c + 4)):
                if 24 <= y <= 39 and 8 <= x <= 15:
                    b[y][x] = (
                        "b" if x in (8, 15) or y == 24 else "g"
                    )
                else:
                    b[y][x] = "w"

    if action not in ("LEFT", "RIGHT", "UP", "DOWN"):
        return src

    initial = (
        src[0][28:32] == "BBBB"
